<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --black: #000000;
      --purple: #7638FA;
      --orange: #FF7A00;
      --text: #151515;
      --muted: #5a5a67;
      --bg: #f9f9fc;
      --surface: #ffffff;
      --radius: 18px;
      --radius-sm: 12px;
      --shadow: 0 14px 36px rgba(40, 20, 80, 0.12);
      --container: min(1200px, 92vw);
    }

    * { box-sizing: border-box; }

    html, body {
      margin: 0;
      padding: 0;
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      color: var(--text);
      background: var(--bg);
      line-height: 1.5;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: var(--container);
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 40;
      backdrop-filter: blur(10px);
      background: rgba(249, 249, 252, 0.9);
      border-bottom: 1px solid rgba(118, 56, 250, 0.08);
    }

    .header-inner {
      min-height: 74px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 0.7rem;
      font-weight: 800;
      font-size: 1.1rem;
      letter-spacing: -0.02em;
    }

    .brand-mark {
      width: 34px;
      height: 34px;
      border-radius: 11px;
      background: linear-gradient(135deg, var(--purple), #c03dff 45%, var(--orange));
      box-shadow: 0 8px 20px rgba(118, 56, 250, 0.35);
    }

    .desktop-nav {
      display: flex;
      align-items: center;
      gap: 1.1rem;
      color: #24242c;
      font-weight: 600;
      font-size: 0.95rem;
    }

    .desktop-nav a {
      padding: 0.45rem 0.7rem;
      border-radius: 10px;
      transition: background 0.2s ease;
    }

    .desktop-nav a:hover { background: rgba(118, 56, 250, 0.08); }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 0.6rem;
    }

    .login-btn, .primary-btn, .store-btn {
      border: 0;
      border-radius: 999px;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
    }

    .login-btn {
      background: var(--black);
      color: white;
      padding: 0.62rem 1rem;
      font-size: 0.9rem;
    }

    .menu-toggle {
      display: none;
      width: 44px;
      height: 44px;
      border-radius: 12px;
      border: 1px solid rgba(20,20,20,0.08);
      background: white;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      padding: 0;
    }

    .menu-toggle span,
    .menu-toggle::before,
    .menu-toggle::after {
      content: "";
      width: 18px;
      height: 2px;
      background: #1f1f1f;
      display: block;
      border-radius: 99px;
      transition: transform 0.25s ease, opacity 0.25s ease;
      position: absolute;
    }

    .menu-toggle span { transform: translateY(0); }
    .menu-toggle::before { transform: translateY(-6px); }
    .menu-toggle::after { transform: translateY(6px); }
    .menu-toggle.is-open span { opacity: 0; }
    .menu-toggle.is-open::before { transform: rotate(45deg); }
    .menu-toggle.is-open::after { transform: rotate(-45deg); }

    .mobile-nav {
      display: none;
      background: white;
      border-top: 1px solid rgba(118,56,250,0.12);
      border-bottom: 1px solid rgba(118,56,250,0.12);
    }

    .mobile-nav.is-open { display: block; }

    .mobile-nav-inner {
      width: var(--container);
      margin: 0 auto;
      padding: 1rem 0 1.2rem;
      display: grid;
      gap: 0.4rem;
    }

    .mobile-nav a {
      padding: 0.7rem 0.2rem;
      font-weight: 600;
      color: #2b2b35;
    }

    .hero {
      padding: 4.7rem 0 3.7rem;
    }

    .hero-panel {
      background:
        radial-gradient(900px 300px at 15% 10%, rgba(118,56,250,0.22), transparent 55%),
        radial-gradient(800px 280px at 85% 85%, rgba(255,122,0,0.22), transparent 60%),
        linear-gradient(140deg, #ffffff 0%, #fcf8ff 46%, #fff8f2 100%);
      border: 1px solid rgba(118,56,250,0.11);
      border-radius: 34px;
      padding: clamp(2rem, 5vw, 4rem);
      box-shadow: var(--shadow);
    }

    .hero h1 {
      margin: 0;
      max-width: 14ch;
      font-size: clamp(2rem, 5vw, 4.25rem);
      line-height: 1.02;
      letter-spacing: -0.04em;
    }

    .hero p {
      margin: 1.2rem 0 2rem;
      max-width: 58ch;
      color: var(--muted);
      font-size: clamp(1rem, 2vw, 1.1rem);
    }

    .primary-btn {
      background: linear-gradient(120deg, var(--purple), #9f43ff 55%, var(--orange));
      color: #fff;
      padding: 0.9rem 1.5rem;
      font-size: 0.97rem;
      box-shadow: 0 10px 22px rgba(118,56,250,0.35);
    }

    .section {
      padding: 2rem 0;
    }

    .info-card {
      background: var(--surface);
      border-radius: 24px;
      padding: clamp(1.5rem, 3vw, 2.2rem);
      border: 1px solid rgba(22,22,22,0.06);
    }

    .section h2 {
      margin: 0;
      font-size: clamp(1.35rem, 2.6vw, 2rem);
      line-height: 1.15;
      letter-spacing: -0.03em;
      max-width: 28ch;
    }

    .section p {
      margin: 0.9rem 0 1rem;
      max-width: 72ch;
      color: var(--muted);
    }

    .link-arrow {
      color: var(--purple);
      font-weight: 700;
    }

    .safety .info-card {
      background: linear-gradient(135deg, #f5f8ff, #f8f5ff 50%, #fff8f3);
      border-color: rgba(118,56,250,0.16);
    }

    .creators .info-card {
      background: linear-gradient(145deg, #fff, #fcf7ff 42%, #fff6ee);
      border-color: rgba(255,122,0,0.22);
    }

    .tagline-banner {
      margin: 2.2rem auto;
      width: var(--container);
      border-radius: 22px;
      padding: 1.3rem 1.5rem;
      color: #fff;
      font-weight: 800;
      font-size: clamp(1.1rem, 2.4vw, 1.8rem);
      letter-spacing: -0.02em;
      background: linear-gradient(120deg, var(--purple), #c13eff 48%, var(--orange));
      box-shadow: 0 14px 30px rgba(95, 47, 180, 0.28);
      text-align: center;
    }

    .news {
      padding: 2.2rem 0;
    }

    .news-top {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .news-label {
      text-transform: uppercase;
      letter-spacing: 0.08em;
      font-size: 0.78rem;
      color: var(--purple);
      margin-bottom: 0.4rem;
      font-weight: 700;
    }

    .news h2 {
      margin: 0;
      font-size: clamp(1.45rem, 2.8vw, 2.2rem);
      letter-spacing: -0.03em;
    }

    .view-more {
      font-weight: 700;
      color: var(--purple);
      white-space: nowrap;
    }

    .news-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(250px, 32%);
      gap: 1rem;
      overflow-x: auto;
      padding: 0.3rem 0.1rem 0.8rem;
      scroll-snap-type: x mandatory;
      scrollbar-width: thin;
      scrollbar-color: rgba(118,56,250,0.45) rgba(118,56,250,0.08);
      -webkit-overflow-scrolling: touch;
    }

    .news-track::-webkit-scrollbar { height: 10px; }
    .news-track::-webkit-scrollbar-track { background: rgba(118,56,250,0.1); border-radius: 99px; }
    .news-track::-webkit-scrollbar-thumb { background: rgba(118,56,250,0.42); border-radius: 99px; }

    .news-card {
      scroll-snap-align: start;
      background: white;
      border-radius: 20px;
      border: 1px solid rgba(24,24,24,0.08);
      overflow: hidden;
      box-shadow: 0 10px 24px rgba(22, 18, 48, 0.09);
      min-height: 355px;
      display: flex;
      flex-direction: column;
    }

    .news-thumb {
      height: 150px;
      background-size: cover;
      background-position: center;
    }

    .thumb-1 { background-image: linear-gradient(130deg, #6028de, #c93cff 50%, #ff8a22); }
    .thumb-2 { background-image: linear-gradient(140deg, #5f37f8, #9144ff 45%, #ff7a00); }
    .thumb-3 { background-image: linear-gradient(120deg, #4830d0, #8e55ff 50%, #f96a00); }
    .thumb-4 { background-image: linear-gradient(140deg, #7638FA, #bf4eff 58%, #ff9b3d); }

    .news-body {
      padding: 1rem 1rem 1.1rem;
      display: flex;
      flex-direction: column;
      gap: 0.8rem;
      flex: 1;
    }

    .tag-list {
      display: flex;
      flex-wrap: wrap;
      gap: 0.45rem;
    }

    .tag {
      font-size: 0.72rem;
      font-weight: 700;
      color: #5a32c2;
      background: #f1eaff;
      border: 1px solid rgba(118,56,250,0.2);
      border-radius: 999px;
      padding: 0.23rem 0.55rem;
    }

    .news-title {
      margin: 0;
      font-size: 1rem;
      line-height: 1.3;
      letter-spacing: -0.01em;
    }

    .date {
      margin-top: auto;
      color: #666677;
      font-size: 0.88rem;
      font-weight: 600;
    }

    .download {
      margin: 1rem 0 0;
      padding: 3rem 0;
    }

    .download-box {
      border-radius: 26px;
      background: #111;
      color: white;
      padding: clamp(1.5rem, 4vw, 2.4rem);
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1.2rem;
      align-items: center;
    }

    .download h3 {
      margin: 0;
      font-size: clamp(1.4rem, 2.7vw, 2.2rem);
      line-height: 1.13;
      letter-spacing: -0.03em;
    }

    .store-group {
      display: flex;
      gap: 0.7rem;
      flex-wrap: wrap;
    }

    .store-btn {
      padding: 0.68rem 1.05rem;
      background: white;
      color: #181818;
      font-size: 0.9rem;
    }

    footer {
      margin-top: 1rem;
      background: #0f0f13;
      color: #ececf1;
      padding: 3rem 0 1.2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(6, minmax(120px, 1fr));
      gap: 1.3rem;
    }

    .footer-col h4 {
      margin: 0 0 0.7rem;
      color: #fff;
      font-size: 0.95rem;
    }

    .footer-col a {
      display: block;
      font-size: 0.88rem;
      color: #c7c7d3;
      margin: 0.36rem 0;
    }

    .footer-col a:hover { color: #fff; }

    .footer-bottom {
      margin-top: 2rem;
      padding-top: 1rem;
      border-top: 1px solid rgba(255,255,255,0.12);
      display: flex;
      flex-wrap: wrap;
      gap: 0.9rem;
      justify-content: space-between;
      align-items: center;
      font-size: 0.82rem;
      color: #c4c4d2;
    }

    .socials, .legal {
      display: flex;
      flex-wrap: wrap;
      gap: 0.7rem;
      align-items: center;
    }

    .social-icon {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      background: rgba(255,255,255,0.08);
      color: #fff;
      font-size: 0.72rem;
      font-weight: 700;
    }

    @media (max-width: 980px) {
      .desktop-nav { display: none; }
      .menu-toggle { display: inline-flex; position: relative; }
      .footer-grid { grid-template-columns: repeat(3, minmax(150px, 1fr)); }
      .news-track { grid-auto-columns: minmax(260px, 45%); }
    }

    @media (max-width: 720px) {
      .hero { padding-top: 2.8rem; }
      .footer-grid { grid-template-columns: repeat(2, minmax(140px, 1fr)); }
      .news-track { grid-auto-columns: 84%; }
      .login-btn { display: none; }
    }

    @media (max-width: 480px) {
      .footer-grid { grid-template-columns: 1fr; }
      .download-box { align-items: flex-start; }
    }
  </style>
</head>
